(function() {
    'use strict';

    class AuthenticLeaderAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Authentic Leader`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Wessex Mutual / Member First).
            this.START_TRUST = 72;        // baseline high-trust culture
            this.TRUST_FLOOR = 55;        // below this the 144-year promise breaks
            this.START_ADOPTION = 12;     // behavioural take-up barely begun
            this.START_EI = 20;           // default style is low-disclosure, task-focused
            this.START_RESISTANCE = 65;   // anchor + her ~60% of the division
            this.BUDGET_CAP = 2.4;        // £2.4m reskilling & support envelope (in £m)
            this.MIN_RESKILL = 1.0;       // below this, redundancies break the promise

            // Targets for a strong, genuine outcome.
            this.TARGET_ADOPTION = 70;
            this.TARGET_TRUST = 70;
            this.TARGET_EI = 70;
            this.TARGET_RESISTANCE = 35;  // lower is better
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    adoption: this.START_ADOPTION,
                    trust: this.START_TRUST,
                    ei: this.START_EI,
                    resistance: this.START_RESISTANCE,
                    budgetUsed: 0,
                    promiseBroken: false,
                    leakBackfired: false,
                    overpromised: false,
                    hiddenTruth: false,
                    adoptionHistory: [this.START_ADOPTION],
                    trustHistory: [this.START_TRUST],
                    eiHistory: [this.START_EI],
                    resistanceHistory: [this.START_RESISTANCE],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    read: `interpret`,
                    gap: `conscious`,
                    ei: `empathy_self`,
                    commit: 60,
                    diagnose: `loss`,
                    intervention: `grow`,
                    honestCommit: `honest`,
                    warmth: 60,
                    frame: `lossrenewal`,
                    truth: 55,
                    voice: `disciplined`,
                    channel: `inperson`,
                    leak: `own`,
                    invest: 2.0,
                    reengage: `advocate`,
                    board: `evidence`
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const read = document.getElementById(`readInput`);
                const gap = document.getElementById(`gapInput`);
                const ei = document.getElementById(`eiInput`);
                const commit = document.getElementById(`commitInput`);
                if (read) decisions.read = read.value;
                if (gap) decisions.gap = gap.value;
                if (ei) decisions.ei = ei.value;
                if (commit) decisions.commit = parseInt(commit.value, 10);
                if (!Number.isFinite(decisions.commit) || decisions.commit < 0 || decisions.commit > 100) {
                    warn(`warn_commit_range`); return false;
                }
            } else if (round === 2) {
                const diag = document.getElementById(`diagnoseInput`);
                const inter = document.getElementById(`interventionInput`);
                const hc = document.getElementById(`honestCommitInput`);
                const warmth = document.getElementById(`warmthInput`);
                if (diag) decisions.diagnose = diag.value;
                if (inter) decisions.intervention = inter.value;
                if (hc) decisions.honestCommit = hc.value;
                if (warmth) decisions.warmth = parseInt(warmth.value, 10);
                if (!Number.isFinite(decisions.warmth) || decisions.warmth < 0 || decisions.warmth > 100) {
                    warn(`warn_warmth_range`); return false;
                }
            } else if (round === 3) {
                const frame = document.getElementById(`frameInput`);
                const truth = document.getElementById(`truthInput`);
                const voice = document.getElementById(`voiceInput`);
                const channel = document.getElementById(`channelInput`);
                if (frame) decisions.frame = frame.value;
                if (truth) decisions.truth = parseInt(truth.value, 10);
                if (voice) decisions.voice = voice.value;
                if (channel) decisions.channel = channel.value;
                if (!Number.isFinite(decisions.truth) || decisions.truth < 0 || decisions.truth > 100) {
                    warn(`warn_truth_range`); return false;
                }
            } else if (round === 4) {
                const leak = document.getElementById(`leakInput`);
                const invest = document.getElementById(`investInput`);
                const re = document.getElementById(`reengageInput`);
                const board = document.getElementById(`boardInput`);
                if (leak) decisions.leak = leak.value;
                if (invest) decisions.invest = parseFloat(invest.value);
                if (re) decisions.reengage = re.value;
                if (board) decisions.board = board.value;
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0) {
                    warn(`warn_invest_negative`); return false;
                }
                if (decisions.invest > this.BUDGET_CAP + 0.001) {
                    warn(`warn_invest_over`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let adoptionDelta = 0, trustDelta = 0, eiDelta = 0, resistanceDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Know yourself first (Common Error 1: skipping self-awareness).
                switch (d.read) {
                    case `interpret`: eiDelta += 14; adoptionDelta += 2; coachKey = `coach_r1_interpret`; break;
                    case `skim`: eiDelta -= 6; adoptionDelta -= 4; coachKey = `coach_r1_skim`; break;
                    case `skip`: eiDelta -= 12; trustDelta -= 4; resistanceDelta += 6; coachKey = `coach_r1_skip`; break;
                }

                // Name the style–situation gap.
                switch (d.gap) {
                    case `conscious`: eiDelta += 12; adoptionDelta += 4; if (d.read === `interpret`) coachKey = `coach_r1_sharp`; break;
                    case `minor`: eiDelta += 2; break;
                    case `none`: eiDelta -= 8; resistanceDelta += 6; coachKey = `coach_r1_nogap`; break;
                }

                // Two EI behaviours to dial up. Empathy + self-regulation is the concept's answer.
                switch (d.ei) {
                    case `empathy_self`: eiDelta += 12; adoptionDelta += 6; trustDelta += 2; break;
                    case `empathy_social`: eiDelta += 6; adoptionDelta += 3; break;
                    case `drive_decisiveness`: eiDelta -= 8; trustDelta -= 3; resistanceDelta += 6; coachKey = `coach_r1_drive`; break;
                    case `optimism_charisma`: eiDelta -= 2; adoptionDelta -= 2; coachKey = `coach_r1_charisma`; break;
                }

                // Commitment to leading consciously, against instinct.
                if (d.commit >= 60) { eiDelta += 6; }
                else if (d.commit <= 25) { eiDelta -= 6; if (coachKey === `coach_default`) coachKey = `coach_r1_lowcommit`; }

                summaryKey = (d.read === `interpret` && d.gap === `conscious` && d.ei === `empathy_self`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Coach the resistant anchor (Common Error 2: commanding her).
                switch (d.diagnose) {
                    case `loss`: adoptionDelta += 8; resistanceDelta -= 10; trustDelta += 2; coachKey = `coach_r2_loss`; break;
                    case `distrust`: adoptionDelta += 4; resistanceDelta -= 6; break;
                    case `ego`: adoptionDelta -= 4; resistanceDelta += 4; coachKey = `coach_r2_ego`; break;
                    case `obstruction`: adoptionDelta -= 6; resistanceDelta += 8; trustDelta -= 4; coachKey = `coach_r2_obstruction`; break;
                }

                // Coaching vs directive intervention.
                switch (d.intervention) {
                    case `grow`: resistanceDelta -= 16; adoptionDelta += 10; trustDelta += 3; if (d.diagnose === `loss`) coachKey = `coach_r2_grow`; break;
                    case `listen`: resistanceDelta -= 8; adoptionDelta += 6; break;
                    case `transact`: resistanceDelta -= 4; trustDelta -= 4; adoptionDelta += 2; coachKey = `coach_r2_transact`; break;
                    case `direct`: resistanceDelta += 14; trustDelta -= 8; adoptionDelta -= 8; coachKey = `coach_r2_direct`; break;
                }

                // Honest commitment vs over-promise (over-promise plants a leak landmine for R4).
                switch (d.honestCommit) {
                    case `honest`: trustDelta += 4; resistanceDelta -= 4; break;
                    case `overpromise`: adoptionDelta += 2; trustDelta -= 6; ds.overpromised = true; coachKey = `coach_r2_overpromise`; break;
                    case `vague`: trustDelta -= 4; resistanceDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r2_vague`; break;
                }

                // Conscious warmth and disclosure (against the low-disclosure default).
                if (d.warmth >= 60) { eiDelta += 6; resistanceDelta -= 4; }
                else if (d.warmth <= 25) { eiDelta -= 6; resistanceDelta += 4; }

                summaryKey = (d.diagnose === `loss` && (d.intervention === `grow` || d.intervention === `listen`) && d.honestCommit === `honest`) ? `sum_r2_good`
                    : (d.intervention === `direct` ? `sum_r2_command` : `sum_r2_weak`);
            } else if (round === 3) {
                // Frame the change message (Common Errors 3 & 4).
                switch (d.frame) {
                    case `lossrenewal`: adoptionDelta += 10; trustDelta += 3; coachKey = `coach_r3_lossrenewal`; break;
                    case `purpose`: adoptionDelta += 6; trustDelta += 2; break;
                    case `opportunity`: adoptionDelta += 2; trustDelta -= 2; coachKey = `coach_r3_opportunity`; break;
                    case `candour`: adoptionDelta += 3; trustDelta -= 2; break;
                }

                // How much hard truth to lead with. A balanced band is best; hiding it plants a leak landmine.
                if (d.truth <= 30) {
                    trustDelta += 2; ds.hiddenTruth = true; coachKey = `coach_r3_overreassure`;
                } else if (d.truth >= 90) {
                    trustDelta -= 6; resistanceDelta += 4; coachKey = `coach_r3_brutal`;
                } else if (d.truth >= 45 && d.truth <= 75) {
                    adoptionDelta += 8; trustDelta += 3;
                } else {
                    adoptionDelta += 3; trustDelta += 2;
                }

                // Authentic voice vs 'unfiltered' (Common Error 3).
                switch (d.voice) {
                    case `disciplined`: eiDelta += 12; adoptionDelta += 8; trustDelta += 3; if (d.frame === `lossrenewal`) coachKey = `coach_r3_disciplined`; break;
                    case `scripted`: eiDelta -= 2; adoptionDelta += 2; coachKey = `coach_r3_scripted`; break;
                    case `unfiltered`: eiDelta -= 10; trustDelta -= 8; resistanceDelta += 8; coachKey = `coach_r3_unfiltered`; break;
                }

                // Delivery channel.
                switch (d.channel) {
                    case `inperson`: adoptionDelta += 8; trustDelta += 2; break;
                    case `cascade`: adoptionDelta += 3; break;
                    case `email`: adoptionDelta -= 4; trustDelta -= 3; break;
                }

                summaryKey = (d.frame === `lossrenewal` && d.voice === `disciplined` && d.truth >= 45 && d.truth <= 75) ? `sum_r3_good`
                    : (ds.hiddenTruth ? `sum_r3_hidden` : `sum_r3_weak`);
            } else if (round === 4) {
                // Lead adoption & rebuild trust under a leak (Common Errors 4 & 5).
                switch (d.leak) {
                    case `own`: trustDelta += 7; adoptionDelta += 5; resistanceDelta -= 4; coachKey = `coach_r4_own`; break;
                    case `deflect`: trustDelta -= 8; resistanceDelta += 6; coachKey = `coach_r4_deflect`; break;
                    case `clampdown`: trustDelta -= 10; resistanceDelta += 10; coachKey = `coach_r4_clampdown`; break;
                }

                // The visible "look after our own" move — funding the human side (Common Error 5).
                spend = Math.min(this.BUDGET_CAP, Math.max(0, d.invest));
                if (d.invest >= 2.0) {
                    adoptionDelta += 10; trustDelta += 6; resistanceDelta -= 8;
                    if (d.leak === `own`) coachKey = `coach_r4_invest_full`;
                } else if (d.invest >= this.MIN_RESKILL) {
                    adoptionDelta += 5; trustDelta += 2;
                } else {
                    // Underfunding forces redundancies that break the 144-year promise.
                    trustDelta -= 16; resistanceDelta += 12; adoptionDelta -= 4;
                    ds.promiseBroken = true; coachKey = `coach_r4_underfund`;
                }

                // Re-engage the resistant manager.
                switch (d.reengage) {
                    case `advocate`: resistanceDelta -= 14; adoptionDelta += 8; trustDelta += 3; break;
                    case `check`: resistanceDelta -= 4; adoptionDelta += 2; break;
                    case `sideline`: resistanceDelta += 10; adoptionDelta -= 6; trustDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r4_sideline`; break;
                }

                // The board adoption read.
                switch (d.board) {
                    case `evidence`: adoptionDelta += 6; trustDelta += 3; break;
                    case `announce`: adoptionDelta -= 4; trustDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r4_announce`; break;
                    case `spin`: trustDelta -= 6; resistanceDelta += 6; if (coachKey === `coach_default`) coachKey = `coach_r4_spin`; break;
                }

                // Deferred landmines: a hidden truth (R3) or an over-promise (R2) detonates at the leak.
                // In a trust culture this is fatal — the leader who wasn't straight pays in collapsing
                // trust and stalled adoption, enough to drop them out of the authentic-leader band.
                if (ds.hiddenTruth || ds.overpromised) {
                    trustDelta -= 18; adoptionDelta -= 10; resistanceDelta += 12; ds.leakBackfired = true;
                    coachKey = ds.hiddenTruth ? `coach_r4_leak_hidden` : `coach_r4_leak_overpromise`;
                }

                summaryKey = (d.leak === `own` && d.invest >= 2.0 && d.reengage === `advocate` && d.board === `evidence` && !ds.leakBackfired) ? `sum_r4_good`
                    : (ds.promiseBroken ? `sum_r4_broken` : `sum_r4_weak`);
            }

            // Resource accounting (Round 4 reskilling commitment).
            ds.budgetUsed = Math.round(Math.min(this.BUDGET_CAP, ds.budgetUsed + spend) * 100) / 100;

            // Apply deltas, clamped 0–100.
            ds.ei = Math.max(0, Math.min(100, ds.ei + eiDelta));
            ds.resistance = Math.max(0, Math.min(100, ds.resistance + resistanceDelta));

            // EI alignment lifts the ceiling on both adoption and trust: conscious, authentic
            // leadership is what makes the change land. A low-EI default style caps the gains.
            const eiFactor = 0.6 + 0.4 * (ds.ei / 100); // 0.6 at EI 0, 1.0 at EI 100
            const adoptionApplied = adoptionDelta > 0 ? adoptionDelta * eiFactor : adoptionDelta;
            const trustApplied = trustDelta > 0 ? trustDelta * eiFactor : trustDelta;

            ds.adoption = Math.max(0, Math.min(100, ds.adoption + adoptionApplied));
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustApplied));

            // The promise breaks if trust falls through the floor at any point.
            if (ds.trust < this.TRUST_FLOOR) ds.promiseBroken = true;

            ds.adoptionHistory.push(Math.round(ds.adoption));
            ds.trustHistory.push(Math.round(ds.trust));
            ds.eiHistory.push(Math.round(ds.ei));
            ds.resistanceHistory.push(Math.round(ds.resistance));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                adoption: Math.round(ds.adoption),
                adoptionDelta: Math.round(adoptionApplied),
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustApplied),
                ei: Math.round(ds.ei),
                eiDelta: Math.round(eiDelta),
                resistance: Math.round(ds.resistance),
                resistanceDelta: Math.round(resistanceDelta),
                budgetUsed: ds.budgetUsed,
                promiseBroken: ds.promiseBroken,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

