        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const adoption = Math.round(ds.adoption);
            const trust = Math.round(ds.trust);
            const ei = Math.round(ds.ei);
            const resistance = Math.round(ds.resistance);
            const composite = Math.round(adoption * 0.30 + trust * 0.30 + ei * 0.20 + (100 - resistance) * 0.20);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.hitAdoption && s.trustHeld && s.resistanceConverted);
            const badge = met
                ? `<span class="authsim-cm-badge authsim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="authsim-cm-badge authsim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const failBadge = s.promiseBroken
                ? ` <span class="authsim-cm-badge authsim-cm-no">` + T(`cm_broken`) + `</span>`
                : (s.leakBackfired ? ` <span class="authsim-cm-badge authsim-cm-no">` + T(`cm_leak`) + `</span>` : ``);
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="authsim-cm-metric"><span class="authsim-cm-mv">` + Math.round(s.adoption || 0) + `</span><span class="authsim-cm-ml">` + T(`cm_m_adoption`) + `</span></div>`
                + `<div class="authsim-cm-metric"><span class="authsim-cm-mv">` + Math.round(s.trust || 0) + `</span><span class="authsim-cm-ml">` + T(`cm_m_trust`) + `</span></div>`
                + `<div class="authsim-cm-metric"><span class="authsim-cm-mv">` + Math.round(s.ei || 0) + `</span><span class="authsim-cm-ml">` + T(`cm_m_ei`) + `</span></div>`
                + `<div class="authsim-cm-metric"><span class="authsim-cm-mv">` + Math.round(s.resistance || 0) + `</span><span class="authsim-cm-ml">` + T(`cm_m_resistance`) + `</span></div>`;
            return ``
                + `<div class="authsim-completion">`
                +   `<div class="authsim-cm-head">`
                +     `<div class="authsim-cm-score">` + score + `<span class="authsim-cm-score-max">/100</span></div>`
                +     `<div class="authsim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="authsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="authsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="authsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const adoption = Math.round(ds.adoption);
            const trust = Math.round(ds.trust);
            const ei = Math.round(ds.ei);
            const resistance = Math.round(ds.resistance);

            const hitAdoption = adoption >= this.TARGET_ADOPTION;
            const trustHeld = trust >= this.TARGET_TRUST && !ds.promiseBroken;
            const resistanceConverted = resistance <= this.TARGET_RESISTANCE;
            // Composite: adoption + trust + EI + resistance reduction, all weighted to 0–100.
            const composite = Math.round(adoption * 0.30 + trust * 0.30 + ei * 0.20 + (100 - resistance) * 0.20);

            let performanceKey = `grade_stalled`;
            if (ds.promiseBroken) performanceKey = `grade_broken`;
            else if (hitAdoption && trustHeld && resistanceConverted && composite >= 75 && ei >= this.TARGET_EI && !ds.leakBackfired) performanceKey = `grade_authentic`;
            else if (hitAdoption && trustHeld && resistanceConverted) performanceKey = `grade_credible`;
            else if (hitAdoption && trustHeld) performanceKey = `grade_adoption_held`;
            else if (trustHeld) performanceKey = `grade_trust_thin`;
            else if (adoption > this.START_ADOPTION + 20) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (ds.promiseBroken) insights.push(window.mySimulation.t(`insight_broken`));
            else if (hitAdoption && trustHeld && resistanceConverted) insights.push(window.mySimulation.t(`insight_authentic`));
            else if (hitAdoption && !trustHeld) insights.push(window.mySimulation.t(`insight_announce`));
            else if (!hitAdoption) insights.push(window.mySimulation.t(`insight_short`));

            if (ds.leakBackfired) insights.push(window.mySimulation.t(`insight_leak`));
            if (ei < 50) insights.push(window.mySimulation.t(`insight_lowei`));
            if (resistance >= 55) insights.push(window.mySimulation.t(`insight_anchor`));
            if (hitAdoption && trustHeld && resistanceConverted && ei >= 70) insights.push(window.mySimulation.t(`insight_disciplined`));

            return {
                adoption: adoption,
                trust: trust,
                ei: ei,
                resistance: resistance,
                hitAdoption: hitAdoption,
                trustHeld: trustHeld,
                resistanceConverted: resistanceConverted,
                leakBackfired: ds.leakBackfired,
                promiseBroken: ds.promiseBroken,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.promiseBroken) return window.mySimulation.t(`hint_broken`);
            if (ds.leakBackfired) return window.mySimulation.t(`hint_leak`);
            if (ds.trust < this.TRUST_FLOOR + 8) return window.mySimulation.t(`hint_trust`);
            if (ds.ei < 45) return window.mySimulation.t(`hint_ei`);
            if (state.currentPeriod >= 2 && ds.resistance >= 55) return window.mySimulation.t(`hint_resistance`);
            if (ds.adoption >= this.TARGET_ADOPTION && ds.trust >= this.TARGET_TRUST && ds.resistance <= this.TARGET_RESISTANCE) return window.mySimulation.t(`hint_strong`);
            return null;
        }

